import{_ as t,o as e,c as o,ai as l}from"./chunks/framework.scx6l_IK.js";const q=JSON.parse('{"title":"不住","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-不住.md","filePath":"50-概念资料/dict-不住.md","lastUpdated":1778155802000}'),i={name:"50-概念资料/dict-不住.md"};function r(u,a,d,n,c,h){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="不住" tabindex="-1">不住 <a class="header-anchor" href="#不住" aria-label="Permalink to &quot;不住&quot;">​</a></h1><blockquote><p>传统：通用/佛家</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>不住（即&quot;无住&quot;）是《金刚经》的核心心法——心不停留在任何一个对象、概念、情绪上，始终保持流动和自由。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;应无所住而生其心——心不要停在任何一个地方，不停留才能生出真正的智慧。&quot;</p></blockquote><blockquote><p>&quot;过去心不可得，现在心不可得，未来心不可得——过去了就过去了，不要抓；还没来的不要提前焦虑；现在的也不要去死抓。&quot;</p></blockquote><blockquote><p>&quot;要无住生心——该住就住，不该住就不住。吃饭就是吃饭，睡觉就是睡觉，不要一边吃饭一边想昨天的事。&quot;</p></blockquote><h2 id="不住的三层含义" tabindex="-1">不住的三层含义 <a class="header-anchor" href="#不住的三层含义" aria-label="Permalink to &quot;不住的三层含义&quot;">​</a></h2><ol><li><strong>不执着于过去</strong> — 过去的错、过去的好，都不要反复回味</li><li><strong>不执着于未来</strong> — 不提前透支焦虑，不被未来的&quot;相&quot;带跑</li><li><strong>不执着于现在</strong> — 即使在美好时刻，也知道它是流动的</li></ol><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-清净心">清净心</a> — 不住的结果就是清净心</li><li><a href="/50-概念资料/dict-平常心">平常心</a> — 不住的日常表现</li><li><a href="/50-概念资料/dict-观照">观照</a> — 不住的具体方法</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 不住的核心应用模型</li><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 连&quot;不住&quot;也不执着</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>做完一件事就放下，不要回头看</li><li>当下正在做什么，心就在什么上</li><li>不忘事，不记事</li></ul>',16)])])}const _=t(i,[["render",r]]);export{q as __pageData,_ as default};
